/**
 * The endpoints of the shared WORK MODAL (`work_modal.xhtml`, generated by tools/lib/work-modal.mjs) as the Java servlets answered them,
 * for the mock backends of every page that includes the modal (Activities now; Schedule, CRM home, Lead detail later).
 *
 *   POST  ../board/schedule/add                              AddScheduleServlet   (movementTypeId dropped, activityGroupId → procedureGroupId, status of the envelope)
 *   PATCH ../board/schedule/edit                             EditScheduleServlet  (id into the path, leadId dropped)
 *   GET   ../board/employees[?saleGroupId=]                  EmployeesServlet
 *   GET   ../board/master/employees-by-activity-group?activityGroupId=
 *   GET   ../board/master/activity-groups?movementTypeId=    MasterActivityGroupsServlet  (also read by the page itself for the colours)
 *
 * The page mock supplies the data (`WorkModalData`); this file is only the servlet layer, so a second page gets the same answers.
 *   GET   ../board/leads?viewMode=list&search=&page=&perPage=…   LeadsBoardServlet  — ONLY the customer search mode of the modal
 *   GET   ../board/lead?id=&activityGroupId=                      LeadDetailServlet  — (ctx.customerSearch: the Schedule page switches it on);
 *                                                                 a page that has no such search leaves `searchLeads` / `leadStep` out and gets a 404.
 *
 * Framework-free (the comparison harness loads it in Node).
 */

/** an answer: HTTP status + the JSON body (or a string) */
export interface MockReply {
  status: number;
  body: unknown;
}

export interface WorkModalEmployee {
  id: number;
  code: string;
  name: string;
  attachFile?: string;
}

export interface WorkModalGroup {
  id: number;
  code: string;
  name: string;
}

/** the answer of the REST service for a schedule write: the envelope `{ status, message, result? , error? }` */
export interface ScheduleEnvelope {
  status: number;
  message?: string;
  result?: unknown;
  error?: { code?: number; message?: string };
}

export interface WorkModalData {
  employees(saleGroupId?: string): WorkModalEmployee[];
  employeesByActivityGroup(activityGroupId: string): WorkModalEmployee[];
  /** null = the product is unknown */
  activityGroups(movementTypeId: string): WorkModalGroup[] | null;
  /** POST /schedules (the body already went through AddScheduleServlet's rewrite) */
  addSchedule(body: Record<string, unknown>): ScheduleEnvelope;
  /** PATCH /schedules/{id} (the body without id and leadId) */
  editSchedule(id: number, body: Record<string, unknown>): ScheduleEnvelope;
  /** the customer search of the modal: `GET /board/leads?viewMode=list…` → the items of `leads.items` and the number of pages */
  searchLeads?(params: URLSearchParams): { items: Record<string, unknown>[]; page: number; perPage: number; total: number; totalPages: number };
  /** `GET /board/lead?id=&activityGroupId=`: what the modal reads (`currentStep.procedureGroupId`); null = the backend refuses */
  leadStep?(id: string, activityGroupId: string | undefined): { status: number; body: unknown };
}

const json = (status: number, body: unknown): MockReply => ({ status, body });
const parse = (raw: string | undefined): Record<string, unknown> | null => {
  try {
    const v = JSON.parse(raw ?? '');
    return v && typeof v === 'object' ? (v as Record<string, unknown>) : null;
  } catch {
    return null;
  }
};

/**
 * @param path    the BFF path without the context path and without a leading `../`: `board/schedule/add`
 * @returns the answer, or null when the path is not one of the work modal's
 */
export function handleWorkModalRequest(method: string, path: string, params: URLSearchParams, rawBody: string | undefined, data: WorkModalData): MockReply | null {
  const m = method.toUpperCase();
  switch (path) {
    case 'board/schedule/add': {
      if (m !== 'POST') return json(405, { error: 'method not allowed' });
      const obj = parse(rawBody);
      if (!obj) return json(500, { status: 500, success: false, message: 'JSONObject text must begin with {' });
      delete obj['movementTypeId'];
      if ('activityGroupId' in obj) {
        const agid = obj['activityGroupId'];
        delete obj['activityGroupId'];
        if (!('procedureGroupId' in obj) && agid != null) obj['procedureGroupId'] = agid;
      }
      const env = data.addSchedule(obj);
      return json(env.status >= 400 ? env.status : 200, env);
    }
    case 'board/schedule/edit': {
      if (m !== 'PATCH' && m !== 'POST') return json(405, { error: 'method not allowed' });
      const obj = parse(rawBody);
      if (!obj || typeof obj['id'] !== 'number') return json(500, { status: 500, success: false, message: "JSONObject[\"id\"] not found." });
      delete obj['leadId'];
      const id = obj['id'] as number;
      delete obj['id'];
      const env = data.editSchedule(id, obj);
      return json(env.status >= 400 ? env.status : 200, env);
    }
    case 'board/employees':
      return json(200, data.employees(params.get('saleGroupId')?.trim() || undefined));
    case 'board/master/employees-by-activity-group': {
      const gid = params.get('activityGroupId')?.trim();
      if (!gid) return json(400, { error: 'activityGroupId required' });
      return json(200, { status: 200, message: 'success', result: data.employeesByActivityGroup(gid) });
    }
    case 'board/master/activity-groups': {
      const mt = params.get('movementTypeId')?.trim();
      if (!mt) return json(400, { error: 'movementTypeId required' });
      const groups = data.activityGroups(mt);
      if (!groups) return json(404, { status: 404, message: 'Not Found', error: { code: 404, message: 'ไม่พบผลิตภัณฑ์' } });
      return json(200, { status: 200, message: 'success', result: { items: groups } });
    }
    case 'board/leads': {
      if (!data.searchLeads) return null;
      const r = data.searchLeads(params);
      return json(200, { id: 0, activityGroupId: 0, usesWorkflowStep: true, leads: { items: r.items, meta: { page: r.page, perPage: r.perPage, total: r.total, totalPages: r.totalPages } } });
    }
    case 'board/lead': {
      if (!data.leadStep) return null;
      const r = data.leadStep((params.get('id') ?? '').trim(), params.get('activityGroupId')?.trim() || undefined);
      return json(r.status, r.body);
    }
    default:
      return null;
  }
}

/** the BFF URL of the page (`../board/x?…`, `/triplesale/board/x`, `/board/x`) → `{ path: 'board/x', params }` */
export function parseBffUrl(input: string): { path: string; params: URLSearchParams } {
  const u = new URL(String(input).replace(/^(?:\.\.\/)+/, '/').replace(/^\/triplesale(?=\/)/, ''), 'http://bff.local');
  return { path: u.pathname.replace(/^\/+/, ''), params: u.searchParams };
}

export function toResponse(r: MockReply): Response {
  const text = typeof r.body === 'string' ? r.body : JSON.stringify(r.body);
  return new Response(text, { status: r.status, headers: { 'Content-Type': 'application/json' } });
}
